def load(res):
    if not res['ok']:
        return {'state': 'error', 'message': f"HTTP {res['status']}"}
    items = res['body'].get('items', [])
    return {'state': 'success', 'items': items} if items else {'state': 'empty'}

print(load({'ok': True, 'status': 200, 'body': {'items': [{'id': 1}]}}))
# {'state': 'success', 'items': [{'id': 1}]}
print(load({'ok': False, 'status': 500, 'body': {}}))
# {'state': 'error', 'message': 'HTTP 500'}
print(load({'ok': True, 'status': 200, 'body': {'items': []}}))
# {'state': 'empty'}
